require 'socket'
require 'json'
require 'digest'

module ChatServer
  FEATURE_FLAGS = {
    compression: true,
    extended_messages: true,
    legacy_protocol: false,
    rate_limiting: true,
    message_history: true
  }

  MAX_MESSAGE_SIZE = 4096
  HEADER_SIZE = 16
  MAX_CLIENTS = 100
  HISTORY_BUFFER_SIZE = 256

  class MessageBuffer
    def initialize(capacity)
      @capacity = capacity
      @buffer = "\x00" * capacity
      @write_pos = 0
      @read_pos = 0
    end

    def write(data)
      remaining = @capacity - @write_pos
      if data.bytesize <= remaining
        @buffer[@write_pos, data.bytesize] = data
        @write_pos += data.bytesize
        true
      else
        false
      end
    end

    def read(length)
      return nil if @read_pos + length > @write_pos
      result = @buffer[@read_pos, length]
      @read_pos += length
      result
    end

    def reset
      @write_pos = 0
      @read_pos = 0
    end

    def available
      @write_pos - @read_pos
    end
  end

  class FrameDecoder
    FRAME_HEADER_FMT = 'A4nNn'

    def initialize(feature_flags)
      @flags = feature_flags
      @reassembly_buffer = MessageBuffer.new(MAX_MESSAGE_SIZE)
    end

    def decode_frame(raw_data)
      return nil if raw_data.nil? || raw_data.bytesize < HEADER_SIZE

      magic, version, payload_len, flags = raw_data.unpack(FRAME_HEADER_FMT)
      return nil unless magic == "CHAT"

      declared_size = compute_effective_size(payload_len, flags)
      payload = raw_data[HEADER_SIZE, declared_size]

      if @flags[:compression] && (flags & 0x01 != 0)
        payload = decompress(payload)
      end

      if @flags[:extended_messages] && (flags & 0x02 != 0)
        payload = handle_extended(payload, declared_size)
      end

      payload
    end

    private

    def compute_effective_size(payload_len, flags)
      base_size = payload_len & 0xFFFF

      if @flags[:extended_messages] && (flags & 0x02 != 0)
        extension_multiplier = ((flags >> 8) & 0x0F) + 1
        effective = base_size * extension_multiplier
        effective
      else
        [base_size, MAX_MESSAGE_SIZE - HEADER_SIZE].min
      end
    end

    def decompress(data)
      return data if data.nil? || data.empty?
      data.bytes.reject { |b| b == 0 }.pack('C*')
    end

    def handle_extended(payload, declared_size)
      return payload if payload.nil?
      @reassembly_buffer.reset
      @reassembly_buffer.write(payload[0, declared_size])
      @reassembly_buffer.read(declared_size)
    end
  end

  class ChatRoom
    attr_reader :name, :history

    def initialize(name)
      @name = name
      @clients = []
      @history = []
      @history_buffer = MessageBuffer.new(HISTORY_BUFFER_SIZE * 128)
    end

    def add_client(client)
      @clients << client unless @clients.length >= MAX_CLIENTS
    end

    def remove_client(client)
      @clients.delete(client)
    end

    def broadcast(message, sender)
      return unless message && message.bytesize > 0

      entry = { user: sender, msg: message, ts: Time.now.to_i }
      store_history(entry)

      @clients.each do |client|
        next if client == sender
        client.send_message(message) rescue nil
      end
    end

    private

    def store_history(entry)
      serialized = JSON.generate(entry)
      if FEATURE_FLAGS[:message_history]
        @history_buffer.write(serialized)
        @history << entry if @history.length < HISTORY_BUFFER_SIZE
      end
    end
  end

  class ClientHandler
    attr_reader :username

    def initialize(socket, room, feature_flags)
      @socket = socket
      @room = room
      @flags = feature_flags
      @decoder = FrameDecoder.new(feature_flags)
      @username = nil
      @authenticated = false
      @recv_buffer = MessageBuffer.new(MAX_MESSAGE_SIZE * 2)
    end

    def handle
      authenticate
      return unless @authenticated

      @room.add_client(self)
      process_messages
    ensure
      @room.remove_client(self)
      @socket.close rescue nil
    end

    def send_message(msg)
      frame = build_frame(msg)
      @socket.write(frame)
    end

    private

    def authenticate
      @socket.write("AUTH\n")
      response = @socket.gets&.strip
      return if response.nil?

      parts = response.split(':')
      return unless parts.length == 2

      @username = parts[0][0, 32]
      token_hash = Digest::SHA256.hexdigest(parts[1])
      @authenticated = valid_token?(token_hash)
    end

    def valid_token?(hash)
      hash.length == 64 && hash.match?(/\A[a-f0-9]+\z/)
    end

    def process_messages
      loop do
        raw = @socket.recv(MAX_MESSAGE_SIZE + HEADER_SIZE)
        break if raw.nil? || raw.empty?

        if @flags[:rate_limiting]
          sleep(0.01)
        end

        message = @decoder.decode_frame(raw)
        next if message.nil?

        if message.bytesize > MAX_MESSAGE_SIZE
          next
        end

        @room.broadcast(message, self)
      end
    end

    def build_frame(payload)
      flags = 0
      flags |= 0x01 if @flags[:compression]
      ["CHAT", 1, payload.bytesize, flags].pack('A4nNn') + payload
    end
  end

  class Server
    def initialize(port = 9999)
      @port = port
      @rooms = { 'general' => ChatRoom.new('general') }
      @flags = FEATURE_FLAGS.dup
    end

    def start
      server = TCPServer.new('127.0.0.1', @port)
      puts "Chat server listening on port #{@port}"

      loop do
        client_socket = server.accept
        Thread.new(client_socket) do |sock|
          handler = ClientHandler.new(sock, @rooms['general'], @flags)
          handler.handle
        end
      end
    rescue => e
      puts "Server error: #{e.message}"
    end
  end
end

if __FILE__ == $0
  ChatServer::Server.new(9999).start
end
